const HALF_W = 32;   // half a tile wide
const HALF_H = 16;   // half a tile tall — the 2:1
const UNIT_Z = 32;   // one step up

// world (x east, y south, z up) -> screen
const iso = (x, y, z) => [
  (x - y) * HALF_W,
  (x + y) * HALF_H - z * UNIT_Z
];

// one colour, three surfaces
const TOP = 1.00, LIT = 0.72, DARK = 0.52;

function face(ctx, tone, base) {
  const [r, g, b] = base;
  ctx.fillStyle = 'rgb(' + [r, g, b].map(c =>
    Math.round(c * tone)).join(',') + ')';
}

